function wordFrequencies(text) {
  const counts = {}; // the map
  for (const word of text.toLowerCase().split(/\s+/).filter(Boolean)) { // each word
    counts[word] = (counts[word] || 0) + 1; // bump
  }
  const entries = Object.entries(counts); // pairs
  entries.sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])); // order
  return entries.slice(0, 3); // top three
}

